using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Diagnostics;using System.Windows.Forms;using Musikbox;using MusikboxTests;
class SearchUI62 {
 static int count;static object Call(object o,string m,params object[] a){return o.GetType().GetMethod(m,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,a);}static void Check(bool ok,string name){if(!ok)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}
 static void Wait(Func<bool> ok){var timer=Stopwatch.StartNew();while(timer.ElapsedMilliseconds<5000){Application.DoEvents();if(timer.ElapsedMilliseconds>=250&&ok())return;System.Threading.Thread.Sleep(10);}throw new Exception("Suchergebnisse nicht innerhalb von 5 Sekunden aktualisiert");}
 static System.Collections.Generic.IEnumerable<Control> All(Control c){yield return c;foreach(Control child in c.Controls)foreach(var v in All(child))yield return v;}
 [STAThread]static int Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);string root=Path.Combine(Path.GetTempPath(),"Musikbox-Suche62-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{using(var v=new MainView(Path.Combine(root,"layout.json"))){var c=new Controller(v,Path.Combine(root,"backups"),new Playback(new PlaybackTestDevice()));var songs=new[]{new Song{Artist="Glen Campbell",Title="Sunflower",Album="Country",Source=Path.Combine(root,"glen.mp3")},new Song{Artist="Lainey Wilson",Title="Heart Like A Truck",Album="Bell Bottom Country",Source=Path.Combine(root,"wilson.mp3")},new Song{Artist="AC/DC",Title="Thunderstruck",Album="The Razors Edge",Source=Path.Combine(root,"acdc.mp3")}};var p=new Project();p.Folders.Add(new BoxFolder{Name="Test",Songs=songs.ToList()});Call(c,"ReplaceProject",p,null,true);v.Show();v.WindowState=FormWindowState.Normal;v.ClientSize=new Size(1500,900);Application.DoEvents();
 Check(String.Join(",",v.Songs.Columns.Cast<DataGridViewColumn>().Where(x=>x.Visible).OrderBy(x=>x.DisplayIndex).Select(x=>x.HeaderText))==String.Join(",",TagSchema.Fields.Where(x=>x.DefaultVisible).Select(x=>x.Name)),"Startstandard: neun sichtbare Felder und drei optionale technische Spalten");
 foreach(string page in new[]{"Bibliothek","Einstellungen","Konvertierung","Covergestaltung"})foreach(string query in new[]{"wilson","Glen Sun","Campbell Glen","ACDC","Sunflower"}){Call(c,"OpenStudioModule",page);v.LibraryMode="Ordner";Call(c,"PopulateLibrary");Check(!v.SongPane.Visible,"Ordneransicht vor Suche");v.SearchBox.Text="";v.SearchBox.Text=query;Wait(()=>v.Songs.Rows.Count==1&&v.SongPane.Visible&&v.Songs.Visible&&!v.Groups.Visible);Check(((Song)v.Songs.Rows[0].Tag).Title==(query=="wilson"?songs[1].Title:query=="ACDC"?songs[2].Title:songs[0].Title),page+" -> Tastatursuche "+query);}
 v.SearchBox.Text="Glen";v.SearchBox.Text="ACD";v.SearchBox.Text="wilson";Wait(()=>v.Songs.Rows.Count==1&&v.Songs.Rows[0].Tag==songs[1]);Check(true,"Schnelle Eingabe verwirft veraltete Ergebnisse");
 for(int i=0;i<2;i++){Call(c,"HandleVoice",(object)new[]{"Glen Sun"});Wait(()=>v.Songs.Rows.Count==1&&v.Songs.Rows[0].Tag==songs[0]);Check(v.SearchBox.Text=="Glen Sun","Erkanntes Wort an gemeinsame Suche, Wiederholung "+i);}
 All(v).OfType<Button>().Single(b=>b.AccessibleName=="Mikrofon ausschalten · Suchtext behalten").PerformClick();Check(v.SearchBox.Text=="Glen Sun","X behaelt erkannten Suchtext");
 var live=(LibraryCounter)Call(c,"BeginImportCounters");live.Add(songs[0]);Wait(()=>All(v).Any(x=>x.AccessibleName=="Titelanzahl"&&x.Text=="Titel: 1"));Check(All(v).Any(x=>x.AccessibleName=="Interpretenanzahl"&&x.Text=="Interpreten: 1"),"Laufende Importanzeige ohne Zusatzfenster");live.Add(songs[0]);Call(c,"EndImportCounters");Check(All(v).Any(x=>x.AccessibleName=="Titelanzahl"&&x.Text=="Titel: 3"),"Abschluss stellt Bibliothekszahlen her");v.Close();}
 Console.WriteLine("BESTANDEN: "+count+" Windows-Such-/Zaehlerpruefungen. Sprachtexte eingespeist; KEIN echter Mikrofontest.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{try{Directory.Delete(root,true);}catch{}}}
}
